SELECT dept_name, CASE WHEN budget >= 4408000 THEN 'high' WHEN budget >= 1413000 THEN 'mid' ELSE 'low' END AS budget_bucket, MAX(budget) AS max_budget, SUM(CASE WHEN dept_name = 'Legal' THEN 1 ELSE 0 END) AS legal_count, SUM(budget) AS total_budget FROM departments GROUP BY dept_name, CASE WHEN budget >= 4408000 THEN 'high' WHEN budget >= 1413000 THEN 'mid' ELSE 'low' END ORDER BY total_budget DESC, dept_name;
